<script setup lang="ts">
import { onMounted,ref,computed } from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import * as api from '@/api/user';import type {User,UserForm} from '@/types/user'
const rows=ref<User[]>([]),q=ref(''),loading=ref(false),dialog=ref(false),editing=ref(false),form=ref<UserForm>({userName:'',userAccount:'',userPwd:'',userPhone:''});const filtered=computed(()=>rows.value.filter(x=>x.userName.includes(q.value)||x.userAccount.includes(q.value)));async function load(){loading.value=true;try{rows.value=await api.getUsers()}finally{loading.value=false}}function open(row?:User){editing.value=!!row;form.value=row?{userName:row.userName,userAccount:row.userAccount,userPhone:row.userPhone,userPwd:''}:{userName:'',userAccount:'',userPwd:'',userPhone:''};dialog.value=true}async function save(){if(!form.value.userName||!form.value.userAccount||(!editing.value&&!form.value.userPwd))return ElMessage.warning('请填写必填字段和密码');const ok=editing.value?await api.updateUser((rows.value.find(x=>x.userAccount===form.value.userAccount)?.userId||0),form.value):await api.createUser(form.value);if(ok!==false){ElMessage.success('保存成功');dialog.value=false;load()}}async function remove(row:User){await ElMessageBox.confirm(`确定删除“${row.userName}”吗？`,'提示',{type:'warning'});if(await api.deleteUser(row.userId)){ElMessage.success('删除成功');load()}}onMounted(load)
</script>
<template><div class="page"><div class="page-header"><h2>用户管理</h2><el-button type="primary" @click="open()">新增用户</el-button></div><div class="card"><div class="filters"><el-input v-model="q" clearable placeholder="搜索用户名或账号" style="max-width:280px"/></div><el-table :data="filtered" v-loading="loading" empty-text="暂无数据"><el-table-column prop="userName" label="用户名"/><el-table-column prop="userAccount" label="账号"/><el-table-column prop="userPhone" label="手机号"/><el-table-column label="操作" width="180"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="editing?'编辑用户':'新增用户'" width="480px"><el-form label-width="90px"><el-form-item label="用户名"><el-input v-model="form.userName"/></el-form-item><el-form-item label="账号"><el-input v-model="form.userAccount"/></el-form-item><el-form-item label="密码"><el-input v-model="form.userPwd" type="password" show-password placeholder="编辑时留空表示不修改"/></el-form-item><el-form-item label="手机号"><el-input v-model="form.userPhone"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
